/** Pages fed to FlashList: events + optional older-edge sentinel.
FlashList is `inverted` so index 0 (newest event) renders at the right edge,
and the older-edge sentinel sits at the left edge. Newer items always arrive
live through the timeline listener, so there's no newer-side sentinel. The
sentinel is only present while there's more history to paginate; once
`reachedStart` flips, it's removed and the last real event is the end. */
const pages = useMemo<ViewerPage[]>(() => {
  const result: ViewerPage[] = events.map((event) => ({
    kind: "event",
    event,
  }));
  if (!reachedStart) {
    result.push({ kind: "older-edge" });
  }
  pagesRef.current = result;
  return result;
}, [events, reachedStart]);

