// When the user lands on the older-edge sentinel after pagination has hit
// the start of history, show the loading spinner for a beat, toast once,
// then snap back to the oldest event so they're not stuck on a blank page.
// Older-edge while still paginating (loading=true) is skipped — real items
// will arrive and replace the sentinel's index naturally.
useEffect(() => {
  if (!currentPage) return;
  if (!hasScrolledInitiallyRef.current) return;
  if (currentPage.kind !== "older-edge" || currentPage.loading) return;

  const timer = setTimeout(() => {
    const page = pagesRef.current[currentIndex];
    if (!page) return;
    if (page.kind !== "older-edge" || page.loading) return;

    if (!toastedEdgesRef.current.has("older")) {
      toastedEdgesRef.current.add("older");
      Toast.show({ type: "info", text1: "No older media" });
    }

    const snapIndex = currentIndex - 1;
    if (snapIndex >= 0) {
      listRef.current?.scrollToIndex({ index: snapIndex, animated: true });
    }
  }, 500);

  return () => clearTimeout(timer);
}, [currentPage, currentIndex]);

input.new_string:
// If `reachedStart` flips while the user is on the older-edge sentinel, the
// sentinel disappears from `pages` and the current index points past the
// end. Snap back to the last real event so the viewer isn't blank.
useEffect(() => {
  if (!reachedStart) return;
  if (currentIndex < events.length) return;
  const targetIndex = Math.max(0, events.length - 1);
  listRef.current?.scrollToIndex({ index: targetIndex, animated: false });
  setCurrentIndex(targetIndex);
}, [reachedStart, events.length, currentIndex]);

