1	import type { MediaSourceInterface } from "@unomed/react-native-matrix-sdk";
2	import { MatrixBaseURL } from "modules/matrix-client/const";
3	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
4	import { fetchMedia } from "modules/matrix-client/utils";
5	import ReactNativeBlobUtil from "react-native-blob-util";
6	import { decryptFile, encryptFile } from "./media-encryption";
7	
8	// Durable ciphertext lives in Caches/ (not backed up, may be purged by iOS
9	// under disk pressure — acceptable, we just re-fetch).
10	const CipherDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir}/encrypted-images`;
11	// Transient plaintext copies for <Image> consumption. Wiped on every app
12	// start so no plaintext survives a kill/relaunch.
13	const TmpDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir}/decrypted-images-tmp`;
14	
15	const PrefixlessCipherDir = CipherDir.replace("file://", "");
16	const PrefixlessTmpDir = TmpDir.replace("file://", "");
17	
18	const InFlight = new Map<string, Promise<string | null>>();
19	const DecryptedLRU = new Map<string, string>();
20	const LRU_MAX = 60;
21	
22	let initPromise: Promise<void> | null = null;
23	
24	function hashKey(input: string): string {
25	  let hash = 0;
26	  for (let i = 0; i < input.length; i++) {
27	    hash = (hash << 5) - hash + input.charCodeAt(i);
28	    hash |= 0;
29	  }
30	  return (hash >>> 0).toString(36);
31	}
32	
33	function getCipherPath(cacheKey: string) {
34	  return `${PrefixlessCipherDir}/${hashKey(cacheKey)}`;
35	}
36	
37	function getTmpPath(cacheKey: string) {
38	  return `${PrefixlessTmpDir}/${hashKey(cacheKey)}`;
39	}
40	
41	async function init(): Promise<void> {
42	  // Wipe any leftover plaintext copies from a previous session.
43	  try {
44	    const tmpExists = await ReactNativeBlobUtil.fs.exists(PrefixlessTmpDir);
45	    if (tmpExists) await ReactNativeBlobUtil.fs.unlink(PrefixlessTmpDir);
46	  } catch {}
47	  await ReactNativeBlobUtil.fs.mkdir(PrefixlessTmpDir);
48	
49	  const cipherExists = await ReactNativeBlobUtil.fs.exists(PrefixlessCipherDir);
50	  if (!cipherExists) await ReactNativeBlobUtil.fs.mkdir(PrefixlessCipherDir);
51	}
52	
53	async function ensureInitialized(): Promise<void> {
54	  if (!initPromise) initPromise = init();
55	  return initPromise;
56	}
57	
58	async function evictLRUIfNeeded(): Promise<void> {
59	  while (DecryptedLRU.size > LRU_MAX) {
60	    const oldest = DecryptedLRU.keys().next().value;
61	    if (!oldest) return;
62	    const path = DecryptedLRU.get(oldest);
63	    DecryptedLRU.delete(oldest);
64	    if (path) {
65	      try {
66	        await ReactNativeBlobUtil.fs.unlink(path);
67	      } catch {}
68	    }
69	  }
70	}
71	
72	interface ResolveProps {
73	  cacheKey: string;
74	  mediaSource: MediaSourceInterface;
75	  mimeType?: string;
76	}
77	
78	/**
79	 * Returns a `file://` URI to a plaintext copy of the image for display.
80	 * Encrypts at rest using AES-256-GCM with a Keychain-stored key. The returned
81	 * path points to a decrypted copy in the tmp dir that is wiped on app start
82	 * and bounded by an in-memory LRU during the session.
83	 */
