30	import { MediaImagePage } from "./MediaImagePage";
31	import { MediaVideoPage } from "./MediaVideoPage";
32	import { getMediaKind } from "./utils";
33	
34	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
35	
36	const OLDER_EDGE_KEY = "__older_edge__";
37	
38	type ViewerPage =
39	  | { kind: "event"; event: EventTimelineItem }
40	  | { kind: "older-edge" };
41	
42	interface Props {
43	  payload: MediaViewerPayload;
44	}
45	
46	export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
47	  const [, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
48	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
49	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
50	  const listRef = useRef<FlashListRef<ViewerPage>>(null);
51	  const [showControls, setShowControls] = useState(true);
52	  const [currentIndex, setCurrentIndex] = useState(0);
53	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
54	  const hasScrolledInitiallyRef = useRef(false);
55	
56	  const room = useMemo<RoomInterface | undefined>(() => {
57	    try {
58	      return MatrixCore.getRoom(payload.roomId);
59	    } catch {
60	      return undefined;
61	    }
62	  }, [payload.roomId]);
63	
64	  const { mediaItems, loadMore, reachedStart } = useMediaTimeline({
65	    room,
66	    roomId: payload.roomId,
67	  });
68	
69	  /** Filtered events in source order (newest first). */
70	  const events = useMemo<EventTimelineItem[]>(() => {
71	    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
72	    return filtered.length === 0 ? [payload.initialEvent] : filtered;
73	  }, [mediaItems, payload.initialEvent]);
74	
75	  /** Pages fed to FlashList: events + optional older-edge sentinel.
76	  FlashList is `inverted` so index 0 (newest event) renders at the right edge,
77	  and the older-edge sentinel sits at the left edge. Newer items always arrive
78	  live through the timeline listener, so there's no newer-side sentinel. The
79	  sentinel is only present while there's more history to paginate; once
80	  `reachedStart` flips, it's removed and the last real event is the end. */
81	  const pages = useMemo<ViewerPage[]>(() => {
82	    const result: ViewerPage[] = events.map((event) => ({
83	      kind: "event",
84	      event,
85	    }));
86	    if (!reachedStart) {
87	      result.push({ kind: "older-edge" });
88	    }
89	    return result;
90	  }, [events, reachedStart]);
91	
92	  /** Pages-index for the tapped event (no offset — events start at index 0). */
93	  const initialPageIndex = useMemo(() => {
94	    const eventIdx = events.findIndex(
95	      (event) => getEventId(event) === payload.initialEventId,
96	    );
97	    return eventIdx >= 0 ? eventIdx : 0;
98	  }, [events, payload.initialEventId]);
99	
100	  // Seed currentIndex so the header shows the tapped event immediately —
101	  // before the FlashList emits its first viewability change.
102	  const seededInitialIndexRef = useRef(false);
103	  if (!seededInitialIndexRef.current) {
104	    seededInitialIndexRef.current = true;
105	    if (currentIndex !== initialPageIndex) setCurrentIndex(initialPageIndex);
106	  }
107	
108	  useEffect(() => {
109	    if (hasScrolledInitiallyRef.current) return;
110	    const eventIdx = events.findIndex(
111	      (event) => getEventId(event) === payload.initialEventId,
112	    );
113	    if (eventIdx < 0) return;
114	    hasScrolledInitiallyRef.current = true;
